// Folder of your daily notes as n8n sees it, and the heading entries go under.
const DAILY_NOTES_DIR = '/files/vault/Daily';
const HEADING = '## Journal';

const body = $json.body ?? {};
const clean = (value, max = 200000) => String(value ?? '').trim().slice(0, max);

const text = clean(body.text);
if (!text) return [{ json: { valid: false, message: 'The field "text" is missing or empty.' } }];

const title = clean(body.title, 200).replace(/\s+/g, ' ');
const id = clean(body.id, 36).toLowerCase().replace(/[^0-9a-f-]/g, '');

// The day and time the entry was written, in the workflow's timezone.
const parsed = DateTime.fromISO(clean(body.createdAt, 100));
const written = (parsed.isValid ? parsed : $now).setZone($now.zoneName);

// The marker is an HTML comment: invisible in Obsidian's reading view, and it
// lets the workflow recognise an entry it has already written.
const marker = id ? `<!-- entry:${id} -->` : '';
const heading = `### ${written.toFormat('HH:mm')}${title ? ` · ${title}` : ''}`;
const block = [heading, ...(marker ? [marker] : []), '', text].join('\n');

const fileName = `${written.toFormat('yyyy-MM-dd')}.md`;
return [{ json: { valid: true, heading: HEADING, marker, block, fileName, filePath: `${DAILY_NOTES_DIR}/${fileName}` } }];

const entry = $('Prepare entry').first().json;

// A missing daily note is fine: the entry then starts a new one.
let existing = '';
if ($input.first()?.binary?.data) {
  existing = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
}

if (entry.marker && existing.includes(entry.marker)) {
  return [{ json: { changed: false, fileName: entry.fileName } }];
}

let note = existing.replace(/\s+$/, '');
const hasHeading = note.split('\n').some(line => line.trim() === entry.heading);
if (entry.heading && !hasHeading) note += `${note ? '\n\n' : ''}${entry.heading}`;
note += `${note ? '\n\n' : ''}${entry.block}\n`;

return [{ json: { changed: true, markdown: note, fileName: entry.fileName, filePath: entry.filePath } }];
